git checkout -q -b fix/issue-12-double-discount && cat >> tests/cart.test.js <<'EOF'

// Issue #12: the customer discount must be applied exactly once.
test('customer discount is applied once (below 10 lines)', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

test('customer discount, then the 5% bulk discount once (10 lines)', () => {
  const lines = Array.from({ length: 10 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(lines, 0.1), 8550); // 10000 * 0.9 * 0.95
});

test('discount rate 0 gives the same total as no discount', () => {
  const lines = Array.from({ length: 10 }, () => ({ price: 11, qty: 1 }));
  assert.equal(total(lines, 0), total(lines));
  assert.equal(total(lines, 0), 105);
});

test('a discounted total drops the fraction below one yen', () => {
  assert.equal(total([{ price: 105, qty: 1 }], 0.1), 94); // 94.5
  assert.equal(total([{ price: 999, qty: 1 }], 0.1), 899); // 899.1
  const lines = Array.from({ length: 10 }, () => ({ price: 111, qty: 1 }));
  assert.equal(total(lines, 0.1), 949); // 1110 * 0.9 * 0.95 = 949.05
});

test('flooring is not thrown off by floating point error', () => {
  // 100 * (1 - 0.29) is 70.99999999999999 in floating point; the exact value is 71.
  assert.equal(total([{ price: 100, qty: 1 }], 0.29), 71);
  assert.equal(total([{ price: 1000, qty: 1 }], 0.3), 700);
});
