// Cart total in yen. `discount` is the customer's discount rate (0.1 = 10%).
// Carts with 10 or more lines get an extra 5% bulk discount, applied once,
// after the customer discount.
//
// Rounding: a total with a customer discount drops the fraction below one yen.
// A total without one (rate 0) keeps rounding the half yen up — wholesale
// invoices (src/invoice.js) depend on that to match the printed price list.
export function total(items, discount = 0) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const bulk = items.length >= 10 ? 0.05 : 0;
  const amount = subtotal * (1 - discount) * (1 - bulk);
  if (discount === 0) return Math.round(amount);
  // The epsilon absorbs floating point error (5 * (1 - 0.8) is 0.9999999999999998,
  // which must not be floored to 0).
  return Math.floor(amount + 1e-6);
}

export function itemCount(items) {
  return items.reduce((n, item) => n + item.qty, 0);
}

